def count_adjacent_dividers(grid, rows, cols, h_lines, v_pos):
    """Count 2's among the given rows/cols that are adjacent to dividers"""
    count = 0
    for r in rows:
        for c in cols:
            if grid[r][c] == 2:
                # Check if adjacent to horizontal divider
                if r == h_lines[0] or r == h_lines[1] or r == h_lines[2]:
                    pass
                # Check if adjacent to vertical divider
                if c == v_pos - 1 or c == v_pos:
                    pass
                # Count adjacent differently
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = r + dr, c + dc
                    # Check if neighbor is a divider
                    if (nr in h_lines or nc == vertical_pos):
                        # Check if the neighbor equals 3
                        if grid[nr][nc] == 3:
                            count += 1
                            break
    return count

